            float height = _sign * sinDna;
            float depth = abs((_sign * 0.5 + 0.5) - (cosDna * 0.25 + 0.5));
            float amzLocal_size = 0.2 + depth * 0.1;
            float amzp_alpha = 1.0 - smoothstep(amzLocal_size - pixelSize,
                                           amzLocal_size + pixelSize,
                                           distance(uv, float2(0.5, height)));
            return float2(
                amzp_alpha,
                depth * amzp_COLOR_DIFFERENCE + (1.0 - amzp_COLOR_DIFFERENCE)
            );
        }
        void amzRender() {
        if( amzPass == 0 ) { amzOutput = amzTexture(0, amzScreenNorm().st); } else if( amzPass==1 ) {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 syamjaidtz;
        syamjaidtz = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        syamjaidtz.y*=layer.y/layer.x;
        syamjaidtz /= amzp_scale;
        syamjaidtz *= rot2m((0.0+amzp_angle)*0.0174533);
        syamjaidtz += float2((0.0+amzp_position.x), (0.0-amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        syamjaidtz /= scaleVec;
     float4 fragColor;
        float TIME = (amzp_autop>0.5)? amzp_PROGRESS + time : amzp_PROGRESS;
            float2 uv = syamjaidtz;
            float amzp_angle = 0.3;
            uv *= float2x2(cos(amzp_angle + float4(0,11,33,0)));
            uv.x -= TIME * 0.5;
            float pixelSize = 10.0 / iResolution.y;
            float2 baseUV = uv;
            uv.x = fract(uv.x);
            float lineIndex = floor(baseUV.x);
            float dnaTimeIndex = lineIndex * amzp_SIN_DENSITY + TIME;
            float sinDna = sin(dnaTimeIndex) * 2.0;
            float cosDna = cos(dnaTimeIndex) * 2.0;
            float lineSDF = abs(uv.x - 0.5);
            float line = smoothstep(pixelSize * 2.0, 0.0, lineSDF);
            float sinCutLineUp = abs(sinDna);
            float sinCutMaskUp = smoothstep(sinCutLineUp + pixelSize, sinCutLineUp - pixelSize, uv.y);
            float sinCutLineDown = -abs(sinDna);
            float sinCutMaskDown = smoothstep(sinCutLineDown - pixelSize, sinCutLineDown + pixelSize, uv.y);
            float2 circle1 = circle(uv, pixelSize, sinDna, cosDna, 1.0);
            float2 circle2 = circle(uv, pixelSize, sinDna, cosDna, -1.0);
            float lineGradient = linearstep(sinCutLineUp, sinCutLineDown, uv.y);
            if (sin(lineIndex * amzp_SIN_DENSITY + TIME) > 0.0) lineGradient = 1.0 - lineGradient;
            lineGradient = mix(circle1.y, circle2.y, lineGradient);
            float helis = 0.0;
            if (circle1.y < circle2.y)
            {
                helis = mix(helis, circle1.y, circle1.x);
                helis = mix(helis, lineGradient, line * sinCutMaskUp * sinCutMaskDown);
             helis = mix(helis, circle2.y, circle2.x);
            }
            else
            {
                helis = mix(helis, circle2.y, circle2.x);
                helis = mix(helis, lineGradient, line * sinCutMaskUp * sinCutMaskDown);
                helis = mix(helis, circle1.y, circle1.x);
            }
            fragColor = float4(helis);
            fragColor.rgb *= amzp_color2.rgb;
     float4 factor = newLayer(amzp_color1,fragColor);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness;
            resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
          }
        }

